function getLumen5Translation(key, lang) {
    if (lumen5Translations[lang] && lumen5Translations[lang][key]) {
        return lumen5Translations[lang][key];
    }
    if (lumen5Translations.en && lumen5Translations.en[key]) {
        return lumen5Translations.en[key];
    }
    return null;
}

function applyLumen5Translations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.lumen5.') || key.startsWith('review.common.'))) {
            const translation = getLumen5Translation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    setTimeout(() => applyLumen5Translations(e.detail.language), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        applyLumen5Translations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
    });
} else {
    applyLumen5Translations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
}


